// Task 4.2.2: Ajv JSON Schema for Products 

// ========================================== 

const productCatalogSchema = { 

    "$schema": "http://json-schema.org/draft-07/schema#", 

    "type": "object", 

    "required": ["products"], 

    "properties": { 

        "products": { 

            "type": "array", 

            "items": { 

                "type": "object", 

                "required": ["id", "title", "handle", "variants"], 

                "properties": { 

                    "id": { "type": "string" }, 

                    "title": { "type": "string" }, 

                    "handle": { "type": "string" }, 

                    "variants": { 

                        "type": "array", 

                        "items": { 

                            "type": "object", 

                            "required": ["id", "title", "product_id"], 

                            "properties": { 

                                "id": { "type": "string" }, 

                                "title": { "type": "string" }, 

                                "product_id": { "type": "string" } 

                            } 

                        } 

                    } 

                } 

            } 

        } 

    } 

}; 



const Ajv = require('ajv'); 

const ajv = new Ajv(); 

const validate = ajv.compile(productCatalogSchema); 



pm.test("[Contract Validation] GET /products adheres to Ajv JSON Schema", function () { 

    const jsonData = pm.response.json(); 

    pm.expect(validate(jsonData)).to.be.true; 

});

