// ========================================== 

// Task 4.2.2: Ajv JSON Schema for Cart 

// ========================================== 

const cartResponseSchema = { 

    "$schema": "http://json-schema.org/draft-07/schema#", 

    "type": "object", 

    "required": ["cart"], 

    "properties": { 

        "cart": { 

            "type": "object", 

            "required": ["id", "items", "region_id", "currency_code"], 

            "properties": { 

                "id": { "type": "string" }, 

                "region_id": { "type": "string" }, 

                "currency_code": { "type": "string" }, 

                "items": { 

                    "type": "array", 

                    "items": { 

                        "type": "object", 

                        "required": ["id", "title", "quantity", "unit_price", "variant_id"], 

                        "properties": { 

                            "id": { "type": "string" }, 

                            "title": { "type": "string" }, 

                            "quantity": { "type": "number" }, 

                            "unit_price": { "type": "number" }, 

                            "variant_id": { "type": "string" } 

                        } 

                    } 

                } 

            } 

        } 

    } 

}; 

 

pm.test("[Contract Validation] GET /carts/{{cartId}} adheres to Ajv JSON Schema", function () { 

    pm.response.to.have.jsonSchema(cartResponseSchema); 

});

pm.test("Cart created with Status 200 or 201", function () { 

    pm.expect(pm.response.code).to.be.oneOf([200, 201]); 

}); 

pm.test("[DDT] Item quantity matches iteration CSV data", function () { 

    let expectedQty = pm.iterationData.get("item_qty"); 

    let responseData = pm.response.json(); 

     

    if (responseData.cart && responseData.cart.items) { 

        let addedItem = responseData.cart.items.find(i => i.variant_id === pm.environment.get("variantId")); 

        pm.expect(addedItem.quantity).to.eql(Number(expectedQty)); 

    } 

});

